function own(){return state?.players[0];}
function viewPlayer(){if(!state)return null;if(alive(own())){if(state.spectateId){state.spectateId=null;state.camera=null;}return own();}const living=state.players.filter(alive);let p=living.find(p=>p.id===state.spectateId);if(!p){p=living[0]||own();state.spectateId=p.id;state.camera=null;}return p;}
function selectSpectator(direction=1,id=null){if(!state||alive(own()))return false;const living=state.players.filter(alive);if(!living.length)return false;let index=living.findIndex(p=>p.id===state.spectateId);const chosen=id?living.find(p=>p.id===id):living[(index+direction+living.length)%living.length];if(!chosen)return false;state.spectateId=chosen.id;state.camera=null;selected=null;heldKeys.clear();heldAttack=false;renderUI();return true;}
function alive(e){return !!e&&e.hp>0;}
function all(){return [...state.players,...state.monsters].filter(alive);}
function cell(x,y){return state.tiles[y]?.[x];}
function occupant(x,y,except){return all().find(e=>e!==except&&(WORLD.contains(e,x,y)||(e.moving&&WORLD.contains({...e,x:e.moving.x,y:e.moving.y},x,y))));}
function canFit(e,x,y,{flying=e?.flying,reservations=true}={}){for(const pos of WORLD.cells({x,y,size:e?.size||1})){const t=cell(pos.x,pos.y);if(!t||t.void||(t.wall&&(!flying||t.wall.tier===5))||occupant(pos.x,pos.y,e)||(reservations&&t.bossAt))return false;}return true;}
function free(x,y,e,size=e?.size||1){return canFit(e||{size},x,y);}
function entityAt(pos,except){return all().find(e=>e!==except&&WORLD.contains(e,pos.x,pos.y));}
function visionOf(p){return 8+(p.relic?.vision||0)+(p.visionUntil>state.clock?p.visionBuff||0:0);}
function canSee(p,pos){return !cell(Math.floor(pos.x),Math.floor(pos.y))?.void&&WORLD.visible(state,p,pos,visionOf(p));}
function remember(force=false){if(!state)return;for(const p of state.players.filter(alive)){const radius=visionOf(p),stamp=p.x+','+p.y+','+radius;if(!force&&p.memoryStamp===stamp&&state.clock-(p.memoryAt??-1)<.16)continue;p.memoryStamp=stamp;p.memoryAt=state.clock;p.memory??={};for(let y=Math.max(0,p.y-radius-1);y<Math.min(state.h,p.y+radius+2);y++)for(let x=Math.max(0,p.x-radius-1);x<Math.min(state.w,p.x+radius+2);x++)if(canSee(p,{x,y})){const t=cell(x,y);p.memory[key(x,y)]={...t,wall:t.wall?{...t.wall,x:t.wall.x??x,y:t.wall.y??y,born:undefined}:null};}}}
function showMap(){if(!state)return;if(modalKind==='map'){closeModal();return;}remember();modal('<div class="intro-kicker">FIELD ATLAS / 探索手记</div><h1>五域残卷</h1><p class="tiny">亮色：当前视野　·　灰色：上次观察的地形与建筑　·　黑色：未知区域。M 返回战场。</p><canvas id="atlas" width="1000" height="620" style="width:100%;height:auto;background:#05090f;border:1px solid #746648"></canvas><div class="atlas-legend">'+Object.values(WORLD.BIOMES).map(b=>'<span style="color:'+b.edge+'">◆ '+b.name+'</span>').join('　')+'</div>','map');const cv=$('atlas'),c=cv.getContext('2d'),s=Math.min(940/state.w,550/state.h),ox=(1000-state.w*s)/2,oy=(620-state.h*s)/2;for(let y=0;y<state.h;y++)for(let x=0;x<state.w;x++){const t=viewPlayer().memory?.[key(x,y)];if(!t)continue;const live=canSee(viewPlayer(),{x,y});c.globalAlpha=live?1:.38;c.fillStyle=WORLD.BIOMES[t.biome].color;c.fillRect(ox+x*s,oy+y*s,s-1,s-1);if(t.wall){c.fillStyle='#ddd4bb';c.fillRect(ox+x*s+2,oy+y*s+2,s-5,s-5);}if(t.chest){c.fillStyle='#ffc66b';c.fillRect(ox+x*s+s*.3,oy+y*s+s*.3,s*.4,s*.4);}}c.globalAlpha=1;for(const e of all())if(e===viewPlayer()||canSee(viewPlayer(),e)){c.fillStyle=WORLD.relationColor(e,viewPlayer());c.beginPath();c.arc(ox+(e.x+.5)*s,oy+(e.y+.5)*s,s*.27,0,7);c.fill();}for(const a of [...state.airdrops,...state.landmarks,...state.nests.filter(n=>n.faction).map(n=>({...n.entity,kind:'raid',landed:true,raidName:n.name}))]){c.fillStyle=a.kind==='core'?'#ffe19a':'#b8f2e4';c.strokeStyle='#071018';c.lineWidth=2;c.fillRect(ox+a.x*s+2,oy+a.y*s+2,s-4,s-4);c.strokeRect(ox+a.x*s+2,oy+a.y*s+2,s-4,s-4);c.font='bold 12px sans-serif';c.fillText(a.kind==='core'?(a.landed?'空投':Math.ceil(a.landAt-state.clock)+'s'):a.kind==='raid'?a.raidName:'事件',ox+(a.x+.5)*s,oy+a.y*s-5);}}

function biomeOf(e){const c=WORLD.center(e);return cell(Math.floor(c.x),Math.floor(c.y))?.biome||'grass';}
function weaponDamage(p){return p.weapon.damage+(p.classId==='ranger'&&p.weapon.ranged?3:0)+(p.weapon.biome===biomeOf(p)?p.weapon.biomeDamage||0:0);}
function animate(e,type,target=e,duration=.55){e.anim={type,left:duration,total:duration,dx:target.x-e.x,dy:target.y-e.y};effect(type==='attack'?'slash':'cast',e.x,e.y,type==='attack'?'#ffd38a':e.color||'#b9eed7',duration);}
function placeWall(pos,c,p){const hp=c.hp+(p?.classId==='builder'?20:0),wall={hp,maxHp:hp,tier:c.tier,size:c.size||1,x:pos.x,y:pos.y,born:state.clock};for(const q of WORLD.cells({...pos,size:wall.size}))cell(q.x,q.y).wall=wall;return wall;}
function randomArea(size=1,biome=null,min=0){const options=[];for(let y=1;y<state.h-size;y++)for(let x=1;x<state.w-size;x++)if(canFit({size},x,y)&&![...state.airdrops,...state.landmarks].some(a=>WORLD.contains({x,y,size},a.x,a.y))&&!cell(x,y).chest&&(!biome||cell(x,y).biome===biome)&&(!min||state.players.every(p=>dist(p,{x,y,size})>=min)))options.push({x,y});return options.length?pick(options):null;}
function randomFree(min=0){for(let i=0;i<2000;i++){const x=1+rnd(state.w-2),y=1+rnd(state.h-2);if(free(x,y)&&!cell(x,y).chest&&(!min||state.players.every(p=>dist(p,{x,y})>=min)))return {x,y};}for(let y=1;y<state.h-1;y++)for(let x=1;x<state.w-1;x++)if(free(x,y)&&!cell(x,y).chest)return{x,y};return null;}
