const HAND_LIMIT=4;
function moveSpeed(e){const slow=e.slowUntil>state.clock?e.slowFactor||.6:1;if(!e.player)return(e.pace??(MONSTER_PACE[e.type]?.[2]||0))*(e.frenzy&&e.hp<e.maxHp*.5?1.35:1)*slow;return Math.max(1.0,2.2+(e.armor.moves||0)*.3+(e.weapon.moves||0)*.3+(e.armor.id==='boots'&&biomeOf(e)==='grass'?.3:0)+(e.hasteUntil>state.clock?1.5:0))*slow;}
function attackCooldown(w){return ({dagger:.6,titan:2.8,cannon:3.1,staff:1.5,storm:1.7,frostbow:1.5,axe:1.45,lavaaxe:1.6})[w.id]*1.3||1.5;}
function itemCooldown(c){return ({heal:8,blink:8,bomb:4,time:25,portal:15,swap:10,haste:10,vision:12,darkness:12,redraw:6,delay:20,advance:15})[c.effect]||4;}
