function fire(source,target,damage,extra={}){const a=WORLD.center({...source,...visualPos(source)}),b=WORLD.center(target),angle=Math.atan2(b.y-a.y,b.x-a.x)+(extra.angle||0),kind=extra.kind||(extra.freeze?'frost':extra.burn?'orb':'arrow');state.projectiles.push({x:a.x,y:a.y,dx:Math.cos(angle),dy:Math.sin(angle),speed:extra.projectileSpeed||10,life:(extra.range||source.range||rangeOf(source))+1,...extra,kind,damage,owner:source,color:extra.color||'#ffe7b3',hitIds:new Set()});effect('muzzle',a.x-.5,a.y-.5,extra.color||source.color,.2);}
